import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Send, Gift } from 'lucide-react';
import axios from 'axios';

const StickyCTA = () => {
  const [showSticky, setShowSticky] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);
  const [email, setEmail] = useState('');
  const [firstName, setFirstName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubscribed, setIsSubscribed] = useState(false);

  useEffect(() => {
    // Check if banner was already dismissed in this session
    const wasDismissed = sessionStorage.getItem('notificationBannerDismissed');
    if (wasDismissed) {
      return;
    }

    const handleScroll = () => {
      // Show sticky CTA after user scrolls past hero section
      const heroHeight = window.innerHeight;
      const scrollPosition = window.scrollY;

      if (scrollPosition > heroHeight * 0.8 && !isDismissed) {
        setShowSticky(true);
      } else {
        setShowSticky(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isDismissed]);

  const handleDismiss = () => {
    setIsDismissed(true);
    setShowSticky(false);
    sessionStorage.setItem('notificationBannerDismissed', 'true');
  };

  const handleSubscribe = async (e) => {
    e.preventDefault();
    if (!email || !firstName) return;

    setIsSubmitting(true);

    try {
      await axios.post('/api/exit-intent', {
        email,
        firstName
      });

      setIsSubscribed(true);
      setTimeout(() => {
        handleDismiss();
      }, 2000);
    } catch (error) {
      console.error('Error subscribing:', error);
      alert('Es gab einen Fehler beim Abonnieren. Bitte versuchen Sie es erneut.');
      setIsSubmitting(false);
    }
  };

  return (
    <AnimatePresence>
      {showSticky && (
        <motion.div
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          className="fixed bottom-0 left-0 right-0 z-40"
        >
          {/* Mobile: Full-width bar */}
          <div className="block sm:hidden">
            <div className="bg-sage-500 text-white px-4 py-4">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center space-x-2">
                  <Gift className="w-5 h-5 text-sage-200" />
                  <div>
                    <p className="text-sm font-semibold">Fesche Deals. Limitierte Plätze.</p>
                    <p className="text-xs text-sage-100">Nur für Abonnenten.</p>
                  </div>
                </div>
                <button
                  onClick={handleDismiss}
                  className="text-white/70 hover:text-white p-1"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {isSubscribed ? (
                <div className="text-center py-2">
                  <p className="text-sm text-sage-100">Du bist dabei!</p>
                </div>
              ) : (
                <form onSubmit={handleSubscribe} className="space-y-2">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={firstName}
                      onChange={(e) => setFirstName(e.target.value)}
                      placeholder="Dein Name"
                      className="w-[35%] px-3 py-2 rounded-lg text-gray-900 text-sm"
                      required
                    />
                    <input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="Deine E-Mail"
                      className="w-[65%] px-3 py-2 rounded-lg text-gray-900 text-sm"
                      required
                    />
                  </div>
                  <button
                    type="submit"
                    disabled={isSubmitting || !email || !firstName}
                    className="w-full bg-white text-sage-600 px-4 py-2 rounded-lg text-sm font-semibold disabled:opacity-50 flex items-center justify-center space-x-2"
                  >
                    <Send className="w-4 h-4" />
                    <span>{isSubmitting ? 'Wird gesendet...' : 'Benachrichtigen'}</span>
                  </button>
                </form>
              )}
            </div>
          </div>

          {/* Desktop: Card-style */}
          <div className="hidden sm:block">
            <div className="max-w-4xl mx-auto mb-6">
              <div className="bg-sage-50 rounded-lg shadow-2xl border border-sage-200 p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4 flex-1">
                    <Gift className="w-6 h-6 text-sage-600" />
                    <div>
                      <p className="text-lg font-semibold text-gray-900">
                        Fesche Deals. Limitierte Plätze.
                      </p>
                      <p className="text-sm text-gray-600">
                        Nur für Abonnenten.
                      </p>
                    </div>
                  </div>

                  {isSubscribed ? (
                    <div className="text-center">
                      <p className="text-sage-600 font-semibold">Du bist dabei!</p>
                    </div>
                  ) : (
                    <form onSubmit={handleSubscribe} className="flex items-center gap-3 flex-1 max-w-md">
                      <input
                        type="text"
                        value={firstName}
                        onChange={(e) => setFirstName(e.target.value)}
                        placeholder="Dein Name"
                        className="w-[35%] px-3 py-2 rounded-lg border border-sage-300 text-gray-900 focus:ring-2 focus:ring-sage-500 focus:border-sage-500 text-sm"
                        required
                      />
                      <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="Deine E-Mail-Adresse"
                        className="w-[65%] px-3 py-2 rounded-lg border border-sage-300 text-gray-900 focus:ring-2 focus:ring-sage-500 focus:border-sage-500 text-sm"
                        required
                      />
                      <button
                        type="submit"
                        disabled={isSubmitting || !email || !firstName}
                        className="bg-sage-500 text-white px-3 py-2 rounded-lg font-semibold disabled:opacity-50 flex items-center hover:bg-sage-600 transition-colors"
                      >
                        <Send className="w-4 h-4" />
                      </button>
                    </form>
                  )}

                  <button
                    onClick={handleDismiss}
                    className="text-gray-400 hover:text-gray-600 p-1 ml-4"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default StickyCTA;
